import { BLOCKED_START_KEYS, DEFAULT_ENDPOINTS, DEFAULT_SESSION_KEY } from "./config";
import { extractErrorCode } from "./errors";
import type { POSProxyConfig, StartArgs } from "./types";

export type EndpointKey = "start" | "status" | "cancel";
export type Body = Record<string, any>;

export class ProxyError extends Error {
  /** errorCode from the response (or one of this package's own codes). */
  readonly code: string;
  /** realCode from the response, e.g. P2P_PAYMENT_INITIATED. */
  readonly realCode?: string;
  readonly serverMessage?: string;

  constructor(code: string, opts: { realCode?: string; serverMessage?: string } = {}) {
    super(code);
    this.name = "ProxyError";
    this.code = code;
    this.realCode = opts.realCode;
    this.serverMessage = opts.serverMessage;
  }
}

export const sleep = (ms: number) => new Promise<void>((r) => setTimeout(r, ms));
export const isAbort = (e: unknown) => (e as Error)?.name === "AbortError";

const isObject = (v: unknown): v is Body => typeof v === "object" && v !== null && !Array.isArray(v);

/** Frappe wraps return values as { message: {...} }. Razorpay's own `message` is a string, so it is left alone. */
const unwrap = (json: unknown): unknown => (isObject(json) && isObject(json.message) ? json.message : json);

const readFrappeMessage = (json: unknown): string | undefined => {
  if (!isObject(json)) return undefined;
  try {
    const list = JSON.parse(String(json._server_messages || "[]"));
    if (Array.isArray(list) && list.length) return JSON.parse(list[0]).message;
  } catch {
    /* ignore */
  }
  return typeof json.message === "string" ? json.message : undefined;
};

/** Build the flat string fields sent to the proxy for "start". Sensitive keys are always dropped. */
export const buildStartFields = (args: StartArgs): Record<string, string> => {
  const { amount, reference, externalRefNumbers, description, ...rest } = args;

  const fields: Record<string, string> = {
    amount: amount.toFixed(2),
    externalRefNumber: reference.trim(),
  };

  for (const [key, value] of Object.entries(rest)) {
    if (BLOCKED_START_KEYS.has(key.toLowerCase()) || value === undefined || value === null) continue;
    const str = Array.isArray(value) ? JSON.stringify(value) : String(value).trim();
    if (str) fields[key] = str;
  }

  if (description?.trim()) fields.description = description.trim().slice(0, 50); // doc: max 50
  if (externalRefNumbers?.length) fields.externalRefNumbers = JSON.stringify(externalRefNumbers);

  return fields;
};

const ENDPOINT_FIELD = {
  start: "startEndpoint",
  status: "statusEndpoint",
  cancel: "cancelEndpoint",
} as const;

/** POST fields to the proxy and return the unwrapped JSON body. Throws ProxyError on HTTP / network errors. */
export const posRequest = async (
  proxy: POSProxyConfig,
  key: EndpointKey,
  fields: Record<string, string>,
  signal?: AbortSignal
): Promise<Body> => {
  let endpoint: string = proxy[ENDPOINT_FIELD[key]] ?? DEFAULT_ENDPOINTS[key];
  if (!endpoint.startsWith("/")) endpoint = `/${endpoint}`;
  const url = `${proxy.url.replace(/\/+$/, "")}${endpoint}`;

  const headers = new Headers(proxy.getHeaders ? await proxy.getHeaders() : undefined);
  headers.set("Accept", "application/json"); // Laravel returns JSON errors instead of HTML redirects

  let body: BodyInit;
  if ((proxy.payloadFormat ?? "form") === "json") {
    headers.set("Content-Type", "application/json");
    body = JSON.stringify(fields);
  } else {
    // No Content-Type here: the browser adds the multipart boundary itself.
    const form = new FormData();
    for (const [k, v] of Object.entries(fields)) form.set(k, v);
    body = form;
  }

  const doFetch = proxy.fetch ?? globalThis.fetch.bind(globalThis);

  let res: Response;
  try {
    res = await doFetch(url, {
      method: "POST",
      headers,
      credentials: proxy.credentials,
      body,
      signal,
    });
  } catch (e) {
    if (isAbort(e)) throw e;
    throw new ProxyError("NETWORK_ERROR");
  }

  let json: unknown = null;
  try {
    json = await res.json();
  } catch {
    /* non-JSON body */
  }

  if (!res.ok) {
    const inner = unwrap(json);
    const text = readFrappeMessage(json);
    const code =
      (isObject(inner) ? inner.errorCode || inner.realCode : undefined) ||
      extractErrorCode(text) ||
      (res.status === 401 || res.status === 403 || res.status === 419
        ? "UNAUTHORIZED"
        : res.status >= 500
        ? "SERVER_ERROR"
        : "UNKNOWN");
    throw new ProxyError(String(code), {
      realCode: isObject(inner) && inner.realCode ? String(inner.realCode) : undefined,
      serverMessage: isObject(inner) && inner.errorMessage ? String(inner.errorMessage) : text,
    });
  }

  const unwrapped = unwrap(json);
  if (!isObject(unwrapped)) throw new ProxyError("SERVER_ERROR");
  return unwrapped;
};

// ---- session persistence (resume after a page refresh) ----

export const saveSession = (key: string, requestId: string, startedAt: number) => {
  try {
    sessionStorage.setItem(key, JSON.stringify({ requestId, startedAt }));
  } catch {
    /* ignore */
  }
};

export const clearSession = (key: string = DEFAULT_SESSION_KEY) => {
  try {
    sessionStorage.removeItem(key);
  } catch {
    /* ignore */
  }
};

export const readSession = (key: string): { requestId?: string; startedAt?: number } | null => {
  try {
    const raw = sessionStorage.getItem(key);
    return raw ? JSON.parse(raw) : null;
  } catch {
    return null;
  }
};
