import type { ButtonState, PaymentPhase, POSButtons, POSLabels, POSTone } from "./types";

export const DEFAULT_LABELS: POSLabels = {
  pay: "Pay",
  sending: "Sending…",
  cancel: "Cancel",
  cancelling: "Cancelling…",
  retry: "Try again",
  checkStatus: "Check status",
  newPayment: "New payment",
  close: "Close",
};

export const PHASE_TEXT: Record<PaymentPhase, string> = {
  idle: "",
  starting: "Sending payment request to the terminal…",
  waiting: "Waiting for the customer to complete payment on the terminal…",
  cancelling: "Cancelling on the terminal…",
  finalizing:
    "The customer is already completing the payment on the terminal. Waiting for the final result…",
  success: "Payment successful.",
  failed: "The payment failed. No money was deducted.",
  cancelled: "Payment cancelled.",
  expired: "The payment request expired. Please try again.",
  timeout: "No response from the terminal, so the request was cancelled. Please try again.",
  unknown: "",
  error: "",
};

/** Detail text for the "still pending" message codes. */
export const STATUS_DETAIL: Record<string, string> = {
  P2P_STATUS_QUEUED: "Payment request is on its way to the terminal…",
  P2P_DEVICE_SENT: "Payment request sent to the terminal…",
  P2P_DEVICE_RECEIVED: "Waiting for the customer to complete payment on the terminal…",
};

const off = (label: string): ButtonState => ({ show: false, disabled: false, loading: false, label });

/**
 * Which buttons to show in each phase.
 *
 *  idle        Pay
 *  starting    Pay (loading) + Cancel (disabled until the request id exists)
 *  waiting     Cancel
 *  cancelling  Cancel (loading)
 *  finalizing  none (the customer already paid on the terminal: only wait)
 *  failed / cancelled / expired / timeout / retryable error   Try again
 *  success / non-retryable error                               New payment / Close
 *  unknown     Check status only (never allow a second charge while the result is unconfirmed)
 */
export const getPosButtons = (
  phase: PaymentPhase,
  retryable: boolean,
  labels: POSLabels = DEFAULT_LABELS
): POSButtons => {
  const pay = off(labels.pay);
  const cancel = off(labels.cancel);
  const retry = off(labels.retry);
  const checkStatus = off(labels.checkStatus);
  const newPayment = off(labels.newPayment);

  switch (phase) {
    case "idle":
      pay.show = true;
      break;
    case "starting":
      pay.show = true;
      pay.disabled = true;
      pay.loading = true;
      pay.label = labels.sending;
      cancel.show = true;
      cancel.disabled = true;
      break;
    case "waiting":
      cancel.show = true;
      break;
    case "cancelling":
      cancel.show = true;
      cancel.disabled = true;
      cancel.loading = true;
      cancel.label = labels.cancelling;
      break;
    case "failed":
    case "cancelled":
    case "expired":
    case "timeout":
      retry.show = true;
      break;
    case "error":
      if (retryable) {
        retry.show = true;
      } else {
        newPayment.show = true;
        newPayment.label = labels.close;
      }
      break;
    case "success":
      newPayment.show = true;
      break;
    case "unknown":
      checkStatus.show = true;
      break;
    case "finalizing":
      break;
  }

  return { pay, cancel, retry, checkStatus, newPayment };
};

export const getTone = (phase: PaymentPhase): POSTone => {
  switch (phase) {
    case "success":
      return "success";
    case "failed":
    case "error":
    case "expired":
    case "timeout":
      return "error";
    case "unknown":
      return "warning";
    default:
      return "neutral";
  }
};

export const TONE_CLASS: Record<POSTone, string> = {
  neutral: "text-gray-700",
  success: "text-green-700",
  error: "text-red-600",
  warning: "text-amber-700",
};
