const CODE_PATTERN = /(EZETAP_\d+|P2P_[A-Z_]+)/;

/** Pull a Razorpay/Ezetap code out of free text (e.g. a Frappe error message). */
export const extractErrorCode = (text?: string | null): string | undefined =>
  text?.match(CODE_PATTERN)?.[1];

/**
 * Map any code to a user-safe error.
 * `fallbackMessage` is only used for codes this package doesn't know (e.g. card-decline codes like
 * EZETAP_1000003 whose server message is already customer-friendly).
 * `overrides` replaces the message for a code.
 */
export const resolvePosError = (
  code?: string | null,
  fallbackMessage?: string | null,
  overrides?: Record<string, string>
): PosError => {
  const known = code ? ERRORS[code] : undefined;
  if (code && known) {
    return { code, message: overrides?.[code] ?? known.message, retryable: known.retryable };
  }
  if (code && overrides?.[code]) {
    return { code, message: overrides[code], retryable: true };
  }
  if (fallbackMessage) {
    return { code: code ?? "UNKNOWN", message: fallbackMessage, retryable: true };
  }
  if (code) {
    return {
      code,
      message: `The payment couldn't be completed (${code}). Please try again or contact support.`,
      retryable: true,
    };
  }
  return { code: "UNKNOWN", message: overrides?.UNKNOWN ?? ERRORS.UNKNOWN.message, retryable: true };
};
