import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { DEFAULT_SESSION_KEY, DEFAULT_TIMING, TICK_MS } from "./config";
import {
  type Body,
  ProxyError,
  buildStartFields,
  clearSession,
  isAbort,
  posRequest,
  readSession,
  saveSession,
  sleep,
} from "./client";
import { resolvePosError } from "./errors";
import {
  DEFAULT_LABELS,
  PHASE_TEXT,
  STATUS_DETAIL,
  TONE_CLASS,
  getPosButtons,
  getTone,
} from "./ui";
import type {
  PaymentPhase,
  PaymentResult,
  PosError,
  StartArgs,
  UseRazorpayPOSBridgeOptions,
  UseRazorpayPOSBridgeReturn,
} from "./types";

/**
 * Razorpay POS Bridge (Ezetap p2padapter) client for React.
 *
 * The browser only ever talks to YOUR proxy. appKey / username / deviceId live on the proxy.
 * Flow follows Razorpay's best practices: Pay -> poll Status every 10s from 30s -> at 150s, if
 * still pending, Cancel. A payment is successful ONLY when status === "AUTHORIZED".
 */

const ALREADY_SKIPPED = ["EZETAP_0000609", "P2P_ALREADY_SKIPPED_ON_USER_END"];
const DUPLICATE_CANCEL = ["EZETAP_0000607", "P2P_DUPLICATE_CANCEL_REQUEST"];
const PAYMENT_INITIATED = ["P2P_PAYMENT_INITIATED"];
const LOOKUP_NOT_FOUND = "EZETAP_0000383";

const CANCELLED_CODES = new Set([
  "P2P_DEVICE_CANCELED",
  "P2P_STATUS_IN_CANCELED_FROM_EXTERNAL_SYSTEM",
]);

const TERMINAL: ReadonlySet<PaymentPhase> = new Set<PaymentPhase>([
  "success",
  "failed",
  "cancelled",
  "expired",
  "timeout",
  "error",
]);

/** A request is on (or on its way to) the terminal. */
const IN_FLIGHT: ReadonlySet<PaymentPhase> = new Set<PaymentPhase>([
  "starting",
  "waiting",
  "cancelling",
  "finalizing",
]);

const matches = (codes: Array<string | null | undefined>, wanted: string[]) =>
  codes.some((c) => !!c && wanted.includes(c));

const errorCodes = (b: Body) => [b.errorCode, b.realCode] as Array<string | undefined>;
const primaryCode = (b: Body): string | undefined => b.errorCode || b.realCode || undefined;

export const useRazorpayPOSBridge = (
  options: UseRazorpayPOSBridgeOptions
): UseRazorpayPOSBridgeReturn => {
  const [phase, setPhase] = useState<PaymentPhase>("idle");
  const [error, setError] = useState<PosError | null>(null);
  const [detail, setDetail] = useState<string | null>(null);
  const [notice, setNotice] = useState<string | null>(null);
  const [requestId, setRequestId] = useState<string | null>(null);
  const [result, setResult] = useState<PaymentResult | null>(null);

  // Latest options without re-creating callbacks
  const cfgRef = useRef(options);
  cfgRef.current = options;

  const getTiming = useCallback(() => ({ ...DEFAULT_TIMING, ...cfgRef.current.timing }), []);
  const storageKey = () => cfgRef.current.sessionKey ?? DEFAULT_SESSION_KEY;
  const persistOn = () => cfgRef.current.persist !== false;
  const err = useCallback(
    (code?: string | null, fallback?: string | null) =>
      resolvePosError(code, fallback, cfgRef.current.messages),
    []
  );

  const phaseRef = useRef<PaymentPhase>("idle");
  const genRef = useRef(0); // bumping this stops any running poll loop
  const startedAtRef = useRef(0);
  const deadlineRef = useRef(0);
  const nextCheckAtRef = useRef(0);
  const cancelSentRef = useRef(false);
  const timedOutRef = useRef(false);
  const lastArgsRef = useRef<StartArgs | null>(null);
  const abortRef = useRef<AbortController | null>(null);

  const getSignal = () => {
    if (!abortRef.current || abortRef.current.signal.aborted) {
      abortRef.current = new AbortController();
    }
    return abortRef.current.signal;
  };

  const go = useCallback((p: PaymentPhase) => {
    phaseRef.current = p;
    setPhase(p);
  }, []);

  /** Move to a final state and stop polling. */
  const finish = useCallback(
    (next: PaymentPhase, e: PosError | null = null, res: PaymentResult | null = null) => {
      genRef.current++;
      if (persistOn()) clearSession(storageKey());
      go(next);
      setError(e);
      setDetail(null);
      setNotice(null);
      setResult(res);
      if (next !== "success") cfgRef.current.onFailure?.(next, e);
    },
    [go]
  );

  const call = useCallback(
    (key: "start" | "status" | "cancel", fields: Record<string, string>) =>
      posRequest(cfgRef.current.proxy, key, fields, getSignal()),
    []
  );

  /** Interpret a status response. Returns true if it is final. */
  const applyStatus = useCallback(
    (body: Body, id: string): boolean => {
      if (TERMINAL.has(phaseRef.current)) return true;

      const status = String(body.status ?? "").toUpperCase();
      const messageCode = String(body.messageCode ?? "");

      // The lookup itself failed (no "status" field).
      if (body.success === false && (body.errorCode || body.realCode) && !status) {
        if (matches(errorCodes(body), ALREADY_SKIPPED)) {
          finish(timedOutRef.current ? "timeout" : "cancelled");
          return true;
        }
        if (body.errorCode === LOOKUP_NOT_FOUND) {
          finish("error", err(LOOKUP_NOT_FOUND));
          return true;
        }
        // Unknown lookup error: never conclude anything that would allow a second charge. Keep polling.
        setNotice("Couldn't refresh the status. Retrying…");
        return false;
      }

      // Per the doc: ONLY status === AUTHORIZED means paid.
      if (status === "AUTHORIZED") {
        const amount = Number(body.amount);
        const res: PaymentResult = {
          p2pRequestId: id,
          txnId: body.txnId || undefined,
          amount: Number.isFinite(amount) && body.amount !== "" ? amount : undefined,
          mode: body.mode || body.paymentMode || undefined,
          cardLastFourDigit: body.cardLastFourDigit || undefined,
          receiptUrl: body.receiptUrl || undefined,
          reference: body.externalRefNumber || undefined,
        };
        finish("success", null, res);
        cfgRef.current.onSuccess?.(res);
        return true;
      }

      if (status === "FAILED") {
        // success:true + errorCode/errorMessage on a failed txn (e.g. card declined)
        const code = body.errorCode as string | undefined;
        finish("failed", code ? err(code, body.errorMessage) : err("TXN_FAILED"));
        return true;
      }

      if (status === "EXPIRED" || messageCode === "P2P_STATUS_IN_EXPIRED") {
        finish("expired");
        return true;
      }

      if (status === "REVERSAL_PENDING") {
        finish("failed", err("REVERSAL_PENDING"));
        return true;
      }

      if (status === "VOIDED" || status === "REFUNDED") {
        finish("failed", err("TXN_REVERSED"));
        return true;
      }

      if (!status && CANCELLED_CODES.has(messageCode)) {
        finish(timedOutRef.current ? "timeout" : "cancelled");
        return true;
      }

      // Still pending: QUEUED / DEVICE_SENT / DEVICE_RECEIVED / STATUS_UNKNOWN / TXN_DONE without a status.
      if (phaseRef.current === "waiting" || phaseRef.current === "starting") {
        go("waiting");
        setDetail(STATUS_DETAIL[messageCode] ?? null);
      }
      return false;
    },
    [finish, go, err]
  );

  const checkOnce = useCallback(
    async (id: string): Promise<boolean> => {
      try {
        const body = await call("status", { p2p_request_id: id });
        return applyStatus(body, id);
      } catch (e) {
        if (!isAbort(e)) setNotice("Couldn't refresh the status. Retrying…");
        return false;
      }
    },
    [call, applyStatus]
  );

  /** Ask the terminal to drop the request. */
  const sendCancel = useCallback(
    async (id: string, reason: "user" | "timeout"): Promise<"ok" | "initiated" | "failed" | "done"> => {
      const markCancelSent = () => {
        cancelSentRef.current = true;
        if (reason === "timeout") timedOutRef.current = true;
        deadlineRef.current = Math.max(deadlineRef.current, Date.now() + getTiming().cancelGraceMs);
        nextCheckAtRef.current = Math.min(nextCheckAtRef.current, Date.now() + 2000); // confirm soon
        if (!TERMINAL.has(phaseRef.current)) {
          go("cancelling");
          setDetail(reason === "timeout" ? "No response from the terminal. Cancelling the request…" : null);
        }
      };

      let codes: Array<string | null | undefined>;
      try {
        const body = await call("cancel", { p2p_request_id: id });
        if (body.success !== false && !body.errorCode) {
          markCancelSent();
          return "ok";
        }
        codes = errorCodes(body);
      } catch (e) {
        if (isAbort(e)) return "failed";
        codes = e instanceof ProxyError ? [e.code, e.realCode] : ["UNKNOWN"];
      }

      // Already skipped/cancelled on the terminal: nothing left to cancel.
      if (matches(codes, ALREADY_SKIPPED)) {
        finish(reason === "timeout" ? "timeout" : "cancelled");
        return "done";
      }
      // Cancel was already requested: treat as accepted and confirm via status.
      if (matches(codes, DUPLICATE_CANCEL)) {
        markCancelSent();
        return "ok";
      }
      // Refused: the customer has already submitted the payment on the device.
      if (matches(codes, PAYMENT_INITIATED)) {
        cancelSentRef.current = true;
        deadlineRef.current = Date.now() + getTiming().initiatedGraceMs;
        nextCheckAtRef.current = Math.min(nextCheckAtRef.current, Date.now() + 2000);
        if (!TERMINAL.has(phaseRef.current)) go("finalizing");
        return "initiated";
      }

      if (reason === "user") setNotice(err(codes.find(Boolean)).message);
      return "failed";
    },
    [call, finish, go, err, getTiming]
  );

  /** Status polling loop (doc: every 10s from 30s; cancel at 150s). */
  const poll = useCallback(
    async (id: string) => {
      const gen = ++genRef.current;
      const alive = () => genRef.current === gen;
      nextCheckAtRef.current = startedAtRef.current + getTiming().pollStartDelayMs;

      while (alive()) {
        const now = Date.now();

        if (now >= deadlineRef.current) {
          if (cancelSentRef.current) {
            finish("unknown", err("STATUS_UNCONFIRMED"));
            return;
          }
          const outcome = await sendCancel(id, "timeout");
          if (!alive()) return;
          if (outcome === "failed") {
            finish("unknown", err("STATUS_UNCONFIRMED"));
            return;
          }
          continue;
        }

        if (now < nextCheckAtRef.current) {
          await sleep(Math.min(TICK_MS, nextCheckAtRef.current - now, deadlineRef.current - now));
          continue;
        }

        nextCheckAtRef.current = Date.now() + getTiming().pollIntervalMs;
        try {
          const body = await call("status", { p2p_request_id: id });
          if (!alive()) return;
          setNotice(null);
          if (applyStatus(body, id)) return;
        } catch (e) {
          if (isAbort(e)) return;
          // transient network/server error: keep polling until the deadline
        }
      }
    },
    [call, applyStatus, sendCancel, finish, err, getTiming]
  );

  const startPayment = useCallback(
    async (args: StartArgs) => {
      if (IN_FLIGHT.has(phaseRef.current) || phaseRef.current === "unknown") return;

      const { amount, reference } = args;
      const validAmount =
        Number.isFinite(amount) && amount > 0 && Math.round(amount * 100) / 100 === amount;
      if (!validAmount) {
        setError(err("INVALID_AMOUNT"));
        return;
      }
      if (!reference?.trim()) {
        setError(err("MISSING_REFERENCE"));
        return;
      }

      lastArgsRef.current = args;
      cancelSentRef.current = false;
      timedOutRef.current = false;
      setError(null);
      setNotice(null);
      setDetail(null);
      setResult(null);
      setRequestId(null);
      go("starting");

      try {
        const body = await call("start", buildStartFields(args));
        if (body.success === false || body.errorCode) {
          throw new ProxyError(primaryCode(body) ?? "UNKNOWN", { realCode: body.realCode });
        }
        const id: string | undefined = body.p2pRequestId || undefined;
        if (!id) throw new ProxyError("UNKNOWN");

        startedAtRef.current = Date.now();
        deadlineRef.current = startedAtRef.current + getTiming().timeoutMs;
        if (persistOn()) saveSession(storageKey(), id, startedAtRef.current);
        setRequestId(id);
        go("waiting");
        void poll(id);
      } catch (e) {
        if (isAbort(e)) return;
        finish("error", err(e instanceof ProxyError ? e.code : "UNKNOWN"));
      }
    },
    [call, poll, finish, go, err, getTiming]
  );

  /** User pressed Cancel. */
  const cancelPayment = useCallback(async () => {
    const id = requestId;
    if (!id || phaseRef.current !== "waiting") return;
    setNotice(null);
    go("cancelling");
    const outcome = await sendCancel(id, "user");
    if (TERMINAL.has(phaseRef.current) || outcome === "done") return;
    if (outcome === "failed") {
      go("waiting"); // let the user try again; sendCancel set a notice
      return;
    }
    await checkOnce(id); // confirm right away instead of waiting for the next poll
  }, [requestId, sendCancel, checkOnce, go]);

  /** From "unknown": look again, and keep polling for a bit longer. */
  const checkStatus = useCallback(async () => {
    const id = requestId;
    if (!id || phaseRef.current !== "unknown") return;
    setNotice(null);
    if (await checkOnce(id)) return;
    deadlineRef.current = Date.now() + 60_000;
    go(cancelSentRef.current ? "cancelling" : "waiting");
    setError(null);
    void poll(id);
  }, [requestId, checkOnce, poll, go]);

  const retry = useCallback(
    (overrides?: Partial<StartArgs>) => {
      if (lastArgsRef.current) void startPayment({ ...lastArgsRef.current, ...overrides } as StartArgs);
    },
    [startPayment]
  );

  /** Back to a clean idle state (only from a final state). */
  const reset = useCallback(() => {
    if (IN_FLIGHT.has(phaseRef.current) || phaseRef.current === "unknown") return;
    genRef.current++;
    if (persistOn()) clearSession(storageKey());
    lastArgsRef.current = null;
    go("idle");
    setError(null);
    setDetail(null);
    setNotice(null);
    setResult(null);
    setRequestId(null);
  }, [go]);

  // Resume an in-flight payment after a page refresh; stop everything on unmount.
  useEffect(() => {
    if (persistOn()) {
      const s = readSession(storageKey());
      const t = getTiming();
      if (s?.requestId && s.startedAt && Date.now() - s.startedAt < t.timeoutMs + 5 * 60_000) {
        startedAtRef.current = s.startedAt;
        deadlineRef.current = s.startedAt + t.timeoutMs;
        cancelSentRef.current = false;
        timedOutRef.current = false;
        setRequestId(s.requestId);
        go("waiting");
        void poll(s.requestId);
      } else if (s) {
        clearSession(storageKey());
      }
    }
    return () => {
      genRef.current++;
      abortRef.current?.abort();
    };
  }, [poll, go, getTiming]);

  const labels = useMemo(() => ({ ...DEFAULT_LABELS, ...options.labels }), [options.labels]);
  const buttons = useMemo(
    () => getPosButtons(phase, !!error?.retryable, labels),
    [phase, error, labels]
  );

  const isBusy = IN_FLIGHT.has(phase);
  const isLocked = isBusy || phase === "unknown";
  const tone = getTone(phase);

  return {
    phase,
    message: error?.message ?? detail ?? PHASE_TEXT[phase],
    notice,
    error,
    requestId,
    result,
    buttons,
    tone,
    toneClass: TONE_CLASS[tone],
    isBusy,
    isLocked,
    inputLocked: isLocked || phase === "success",
    startPayment,
    cancelPayment,
    checkStatus,
    retry,
    reset,
  };
};

export default useRazorpayPOSBridge;
