import type { POSTimingConfig } from "./types";

export const DEFAULT_SESSION_KEY = "razorpay_pos_active_payment";

/** Razorpay best practice: first status check at 30s, every 10s, cancel at 150s. */
export const DEFAULT_TIMING: Required<POSTimingConfig> = {
  pollStartDelayMs: 30_000,
  pollIntervalMs: 10_000,
  timeoutMs: 150_000,
  cancelGraceMs: 30_000,
  initiatedGraceMs: 60_000,
};

export const DEFAULT_ENDPOINTS = {
  start: "/api/start",
  status: "/api/status",
  cancel: "/api/cancel",
} as const;

/**
 * Terminal / credential fields that must never leave the browser even if a caller passes them.
 * Compared case-insensitively.
 */
export const BLOCKED_START_KEYS: ReadonlySet<string> = new Set(
  [
    "appKey",
    "username",
    "pushTo",
    "deviceId",
    "deviceSerial",
    "orgCode",
    "merchantCode",
    "mid",
    "tid",
  ].map((k) => k.toLowerCase())
);

/** Poll loop wake-up interval. Small so a Cancel is picked up quickly. */
export const TICK_MS = 250;
